// src/anthropic.ts
init_sdk();
var MILLICENT_PER_INPUT_MTOK = 5 * 100 * 10;
var MILLICENT_PER_OUTPUT_MTOK = 25 * 100 * 10;
function costInMillicents(inputTokens, outputTokens) {
  return Math.ceil(
    inputTokens * MILLICENT_PER_INPUT_MTOK / 1e6 + outputTokens * MILLICENT_PER_OUTPUT_MTOK / 1e6
  );
}
function assistantConfigured() {
  const key = process.env["ANTHROPIC_API_KEY"];
  return key !== void 0 && key.trim() !== "";
}
function anthropicClient() {
  const client = new Anthropic();
  return {
    async complete(request) {
      const response = await client.beta.messages.create({
        model: "claude-opus-5",
        max_tokens: 4e3,
        betas: ["server-side-fallback-2026-07-01"],
        fallbacks: "default",
        thinking: { type: "adaptive" },
        output_config: { effort: "medium" },
        system: request.system,
        messages: request.messages
      });
      const text = response.content.filter((block) => block.type === "text").map((block) => block.text).join("\n").trim();
      return {
        text,
        inputTokens: response.usage.input_tokens,
        outputTokens: response.usage.output_tokens,
        refused: response.stop_reason === "refusal"
      };
    }
  };
}

// src/assistant-guardrails.ts
var RECHT = [
  /§/,
  /\bbgb\b/i,
  /\bvob\b/i,
  /\begbgb\b/i,
  /verjähr/i,
  /gewährleist/i,
  /\bkündig/i,
  /\bklag(e|en|t)\b/i,
  /anwalt|anwält|rechtsanwalt/i,
  /vertragsstrafe/i,
  /schadenersatz|schadensersatz/i,
  /\bhaftung\b|\bhaftbar\b/i,
  /\bminderung\b/i,
  /\bzurückbehalt/i,
  /\bmahnung\b|\bin verzug setzen\b/i,
  /\babnahmeverweigerung\b/i,
  /\brechtlich\b|\brechtens\b|\bdarf (er|der gu|die firma)\b/i
];
var BEFUND = [
  /\bmangel\b|\bmängel\b|\bmangelhaft\b/i,
  /\briss\b|\brisse\b|\brissbildung\b/i,
  /\bfeucht/i,
  /\bschimmel\b/i,
  /\babplatzung|\babgeplatzt\b/i,
  /\bhohlstelle|\bhohl klingt\b/i,
  /\bkiesnest\b|\blunker\b/i,
  /\bverfärb/i,
  /\bschief\b|\buneben\b|\bnicht im lot\b|\bnicht in waage\b/i,
  /\bfleck(en)?\b/i
];
var BEWERTUNG = [
  /ist das (schlimm|normal|ein mangel|noch in ordnung|so richtig|zulässig)/i,
  /muss das so/i,
  /darf das so/i,
  /\bfoto\b|\bbild\b|\baufnahme\b/i,
  /siehst du|erkennst du|was sagst du dazu/i,
  /\bschlimm\b|\bnormal\b|\bin ordnung\b|\bakzeptabel\b|\btolerierbar\b/i,
  /\bbedenklich\b|\bgefährlich\b/i
];
var KOSTEN = [
  /\bkostet\b|\bkosten\b|\bpreis\b|\bpreise\b/i,
  /\bteuer\b|\bgünstig\b/i,
  /\beuro\b|€/,
  /\bbudget\b/i,
  /was zahle ich|was muss ich zahlen/i
];
var trifft = (muster, text) => muster.some((regel) => regel.test(text));
function classifyQuestion(question) {
  const gefunden = [];
  if (trifft(RECHT, question)) gefunden.push("recht");
  if (trifft(BEFUND, question) && trifft(BEWERTUNG, question)) gefunden.push("mangel");
  if (trifft(KOSTEN, question)) gefunden.push("kosten");
  return gefunden;
}
var GUARDRAIL_INSTRUCTION = {
  recht: "Diese Frage hat einen rechtlichen Kern. Nenne die einschl\xE4gige Gesetzesstelle (BGB, VOB/B, EGBGB) und was dort steht \u2014 sachlich, ohne sie auf diesen Fall anzuwenden. Sag ausdr\xFCcklich, dass die Bewertung des Einzelfalls zu einem Anwalt geh\xF6rt. Bewerte nicht, wer im Recht ist.",
  mangel: "Diese Frage zielt auf die Bewertung eines Befundes am Bau. Beschreibe, was typischerweise dahintersteckt und woran man es unterscheidet, aber urteile nicht, ob es ein Mangel ist \u2014 das kann niemand aus der Ferne und schon gar nicht von einem Foto. Verweise auf einen Bausachverst\xE4ndigen vor Ort und sag, was der Bauherr bis dahin dokumentieren sollte.",
  kosten: "Diese Frage ber\xFChrt Geld. Nenne h\xF6chstens Gr\xF6\xDFenordnungen und sag dazu, woher sie stammen. Gib keine Zahl, die als verbindliche Sch\xE4tzung missverstanden werden kann \u2014 verbindlich ist nur ein Angebot."
};
var GUARDRAIL_NOTE = {
  recht: "Hinweis auf eine Gesetzesstelle, keine Rechtsberatung. Ob sie in deinem Fall greift, sagt dir ein Anwalt f\xFCr Bau- und Architektenrecht \u2014 f\xFCr die erste Einsch\xE4tzung gen\xFCgt oft ein Beratungsgespr\xE4ch.",
  mangel: "Ob das ein Mangel ist, entscheidet niemand aus der Ferne. Das kann nur ein Bausachverst\xE4ndiger vor Ort, und bis dahin hilft eines: fotografieren, mit Ma\xDFstab daneben, und ins Bautagebuch eintragen.",
  kosten: "Gr\xF6\xDFenordnungen, keine Kostensch\xE4tzung. Verbindlich ist allein ein Angebot \u2014 hol dir zwei, dann siehst du auch, wie belastbar die Zahl ist."
};
function withGuardrailNotes(answer, guardrails) {
  const fehlende = guardrails.map((rail) => GUARDRAIL_NOTE[rail]).filter((note) => !answer.includes(note));
  if (fehlende.length === 0) return answer;
  return `${answer.trimEnd()}

${fehlende.join("\n\n")}`;
}

